<script setup>
import {ref,watch} from 'vue';
import NoteReviewActions from './NoteReviewActions.vue';
import api from '../../services/api.js';
const props=defineProps({agencyId:[Number,String],own:Boolean,queue:Boolean});
const results=ref([]),error=ref(''),busy=ref(false),nextBefore=ref(null),below=ref(props.queue?70:'');let generation=0;
async function load(more=false){if(!props.agencyId)return;const current=++generation;busy.value=true;error.value='';try{const {data}=await api.get('/narriva/review-results',{params:{agencyId:props.agencyId,scope:props.own?'mine':undefined,view:props.queue?'signed':undefined,below:props.queue?below.value:undefined,before:more?nextBefore.value:undefined},skipGlobalLoading:true});if(current!==generation)return;results.value=more?[...results.value,...(data.results || [])]:data.results || [];nextBefore.value=data.nextBefore;}catch(e){if(current===generation)error.value=e.response?.data?.error?.message || 'Review results could not be loaded.';}finally{if(current===generation)busy.value=false;}}
function openNote(row){window.location.assign('/note-aid?'+new URLSearchParams({noteId:row.noteId,agencyId:props.agencyId}));}
watch(()=>[props.agencyId,props.own],()=>{generation++;results.value=[];error.value='';nextBefore.value=null;busy.value=false;});
</script>
<template><details class="review-results" @toggle="$event.target.open && !results.length && !busy && load()"><summary>{{ own?'Your note review results':queue?'Documentation follow-up':'Note review results' }}</summary><p v-if="!queue">Scores and recorded decisions for completed reviews.</p><div v-else class="review-threshold"><label>Below score (%) <input v-model.number="below" type="number" min="1" max="100" @keydown.enter.prevent="load()" /></label><button type="button" :disabled="busy" @click="load()">Apply</button></div><button type="button" :disabled="busy" @click="load()">Refresh</button><p v-if="error" role="alert">{{ error }}</p><div class="review-results-scroll"><table v-if="results.length"><thead><tr><th>Completed</th><th>Author</th><th>Record</th><th>Service</th><th>Quality</th><th>Decisions</th><th>Status</th><th v-if="queue">Missing in the note</th></tr></thead><tbody><tr v-for="row in results" :key="row.id"><td>{{ row.completedAt ? new Date(row.completedAt).toLocaleString() : '—' }}</td><td>{{row.authorName || '#'+row.authorUserId}}</td><td>{{ row.noteId?'Note #'+row.noteId:'Draft #'+row.draftId }} · {{ row.phase==='pre_generation'?'Draft review':'Output review' }}</td><td>{{ row.serviceCode }}</td><td><strong>{{ row.score===null?'Unavailable':row.score+'%' }}</strong></td><td>{{ row.manualEdited?'Manual edit · ':'' }}{{ row.keptAsWritten.length }} kept as written{{ row.qualityKept?' · Quality kept':'' }}</td><td>{{ row.status }}</td><td v-if="queue" class="quality-details">
  <ul><li v-for="item in row.missing" :key="item.label"><strong>{{ item.label }}</strong> <span>{{ item.message }}</span></li></ul>
  <NoteReviewActions :item="{noteId:row.noteId,agencyId}" @open-note="openNote" />
</td></tr></tbody></table></div><p v-if="!results.length && !busy && !error">{{queue?'No matching reviews on this page.':'No completed reviews.'}}</p><button v-if="nextBefore" type="button" :disabled="busy" @click="load(true)">Load earlier reviews</button></details></template>
<style scoped>.review-results{border:1px solid #cfdee9;border-radius:10px;padding:16px;background:#fff;color:#214158;margin:16px 0;font-size:13px}.review-results summary{font-weight:650;cursor:pointer}.review-results p{font-size:12px;line-height:1.5;color:#5a7181}.review-results-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;margin-top:12px}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #e2eaf0;white-space:nowrap}button{font:inherit;border:1px solid #bad0df;background:#f3f8fc;border-radius:7px;padding:8px 12px;color:#235a7d}.quality-details{white-space:normal;min-width:250px}.quality-details ul{margin:0 0 6px;padding-left:16px}.review-threshold{display:flex;gap:8px;align-items:center;margin:8px 0}.review-threshold input{width:65px}</style>
